INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000033',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about past personal experiences in Kannada","Use the past tense forms of common verbs","Express what you have done before using munde"],"explanation":{"intro":"Past experiences covers how to talk about what you have done, places you have visited, and things you have tried in the past in Kannada.","culturalNote":"Sharing experiences in Karnataka: in social settings, Kannadigas often talk about their last travel experience, the restaurant they visited, or cultural events they attended. Kannada culture places great importance on sharing experiences with family and community. Pilgrimage travel is very common — Udupi Sri Krishna Temple (famous for udupi cuisine origin), Kukke Subramanya (snake deity — very popular among Kannadigas), Dharmasthala (Jain-Hindu syncretism — very inclusive), Sabarimala (Ayyappa pilgrimage — shared across Karnataka and Kerala). Nature experiences: Western Ghats trekking is very popular — Kumara Parvatha (1712m — tough one-day trek), Kudremukh peak, Baba Budangiri. Food experiences: eating a traditional saapadu (banana leaf meal) at a South Karnataka wedding is considered a must-do experience. Unique experiences: watching the Mysuru Dasara elephant procession live (Jumboo Savari)."},"examples":[{"sentence":"Naanu munde Hampi ge hogi bande haagu alli sulada niru kande.","english":"I had gone to Hampi earlier and saw the churning water there."},{"sentence":"Naanu ee hottagi Mysuru Palace nodida, thumba channa itu.","english":"I had seen Mysuru Palace once before, it was very beautiful."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about my past experiences and things I have done before in Kannada."}}',
'{"items":[{"word":"munde","translation":"before/earlier/previously","transliteration":"munde","pronunciation":"MUN-de","example":"naanu munde hode"},{"word":"ee hottagi","translation":"once (before) / at one time","transliteration":"ee hottagi","pronunciation":"ee HOT-ta-gi","example":"ee hottagi hoge bande"},{"word":"hogi bande","translation":"went and came back (went and returned)","transliteration":"hogi bande","pronunciation":"HO-gi BAN-de","example":"Mysuru ge hogi bande"},{"word":"nenu","translation":"see (past: nodide)","transliteration":"nenu","pronunciation":"NE-nu","example":"nenu / nodide"},{"word":"tini bande","translation":"went and ate (ate and came back)","transliteration":"tini bande","pronunciation":"TI-ni BAN-de","example":"hotel ge hogi tini bande"},{"word":"otagitta","translation":"swam in (swam — past from heemade maadu)","transliteration":"otagitta","pronunciation":"o-ta-GIT-ta","example":"kere alli otagitta"}]}',
'{"title":"Naanu munde X hogi bande — I had gone to X before (past experience)","pattern":"Naanu munde X ge hogi bande = I had gone to X before (and returned). Munde = before/previously. Hogi bande = went-and-came (compound verb: hogi = having gone, bande = came). Regular past: hode (went), bande (came), tinde (ate), nodide (saw), maadide (did), kande (saw/found). Before doing: X maadida munde = before doing X. First time: modalettu sala = for the first time (modalettu = first).","explanation":"Past experience in Kannada: use past tense verb + munde for previously. Common past forms: hode (went), bande (came), tinde (ate), nodide (saw), maadide (did), kande (saw/found), keLide (listened), odide (read), kalide (learned). Compound action: hogi + main verb = went and X (hogi tinde = went and ate). Return: hogi bande = went and returned. First time (never done before): naanu modalettu X ge hodini (I went to X for the first time). Never done before: naanu ondu sala X maadilla (I have not done X even once). Would like to do: naakke X maadabeku itu (I wanted to do X).","examples":[{"sentence":"Naanu modalettu Western Ghats alli trekking maadida.","english":"I went trekking in the Western Ghats for the first time."},{"sentence":"Naanu ondu sala Kukke Subramanya ge hogi bande — thumba peaceful itu.","english":"I once went to Kukke Subramanya and came back — it was very peaceful."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"munde means?","options":["before/earlier/previously","after","soon","never"],"correctAnswer":"before/earlier/previously"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I had gone to Hampi earlier and saw the churning water there.","options":["Naanu munde Hampi ge hogi bande haagu alli sulada niru kande.","Naanu inja Hampi ge hogi bande haagu alli sulada niru kande.","Naanu munde Mysuru ge hogi bande haagu alli sulada niru kande.","Naanu munde Hampi ge hogi bande aadare alli sulada niru kande."],"correctAnswer":"Naanu munde Hampi ge hogi bande haagu alli sulada niru kande."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Naanu ___ sala Western Ghats alli trekking maadida.","options":["modalettu","munde","ee hottagi","naale"],"correctAnswer":"modalettu"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I once went to Kukke Subramanya and came back.","wordBankItems":["Naanu","ondu","sala","Kukke","Subramanya","ge","hogi","bande","."],"correctAnswer":"Naanu ondu sala Kukke Subramanya ge hogi bande ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"hogi bande means?","options":["went and came back","came and went","went away","came here"],"correctAnswer":"went and came back"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000034',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about future plans in Kannada","Use hoguttini and hogona for future intention","Express plans with certainty and uncertainty"],"explanation":{"intro":"Future plans and intentions covers how to describe what you intend to do, your upcoming plans, and how to express certainty or uncertainty about future events in Kannada.","culturalNote":"Planning culture in Karnataka: Kannadigas tend to plan methodically — especially for festivals, pilgrimages, and family events. New Year planning: Ugaadi (Kannada New Year — typically March/April) is a time for new plans and resolutions. Harvest festivals: Makara Sankranti (January 14) — planning for the festive gatherings. Education plans: very common topic — IIT/IIM/NEET/JEE preparations, studying abroad. Career planning: MBA (MBA maadabeku), IAS (UPSC) preparation. Wedding planning: shaadi date decide aaythilla (wedding date hasn''t been decided yet) is a very common topic in family gatherings. Travel plans: Goa trip planning is very popular for Bengalurians (5-6 hour drive). Summer vacation plans: hill station trips (Ooty, Kodagu, Chikmagalur)."},"examples":[{"sentence":"Naale naanu nanna maneyavaralli koodi Nandi Hills ge hoguttini.","english":"Tomorrow I am going to Nandi Hills together with my family."},{"sentence":"Munde ella naanu MBA maadabeku anta plan iddini.","english":"Sometime ahead I plan to do an MBA."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can describe my future plans and intentions in Kannada."}}',
'{"items":[{"word":"plan","translation":"plan","transliteration":"plan","pronunciation":"plaan","example":"naanu plan maadide"},{"word":"yochane","translation":"thought/plan/intention","transliteration":"yochane","pronunciation":"YO-cha-ne","example":"nanna yochane"},{"word":"aakaankshe","translation":"wish/aspiration/desire","transliteration":"aakaankshe","pronunciation":"aa-KAAN-kshe","example":"nanna aakaankshe"},{"word":"nishchaya","translation":"certainty/determination","transliteration":"nishchaya","pronunciation":"NISH-cha-ya","example":"nishchayavaagi"},{"word":"munde ella","translation":"sometime in the future","transliteration":"munde ella","pronunciation":"MUN-de EL-la","example":"munde ella maadabeku"},{"word":"plan maadida","translation":"have planned (completed planning)","transliteration":"plan maadida","pronunciation":"plaan MAA-di-da","example":"hoguvudu plan maadida"}]}',
'{"title":"Naanu X hoguttini — I am going to X (future plan in Kannada)","pattern":"Naanu X hoguttini = I am going to X (near future plan). Naalu X hogona = let''s go to X together (suggestion for future). X maadabeku anta plan iddini = I plan to do X (longer term intention). Certainty marker: nishchayavaagi X maaduttini (I will definitely do X). Uncertainty: belki/shaayada X maaduttini (maybe I will do X — belki/shaayada = maybe).","explanation":"Future plans in Kannada: present tense -uttini can function as near future (I am going = I will go). More specifically future: X maaduttini (I will do X). Plan/intention: X maadabeku anta nambuttini (I believe I need to do X). Letting someone know of a plan: naanu X ge hoguttini, neevu baruttiravaa? (I am going to X, will you come? — baruttiravaa = will you come? — formal question). Inviting to join a future plan: koodi hogona (let''s go together — koodi = together). Upcoming event: X ki bhaluu ready maaduttiddeeni (I am getting very ready for X — bhaluu = very — Urdu borrowed).","examples":[{"sentence":"Naanu Goa trip ge nishchayavaagi hoguttini, ticket book maadide.","english":"I will definitely go on a Goa trip, I have booked a ticket."},{"sentence":"Neevu baruttiravaa? Koodi hogona, thumba channa aguttade.","english":"Will you come? Let''s go together, it will be very good."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"munde ella means?","options":["sometime in the future","just now","yesterday","last time"],"correctAnswer":"sometime in the future"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Tomorrow I am going to Nandi Hills together with my family.","options":["Naale naanu nanna maneyavaralli koodi Nandi Hills ge hoguttini.","Ninne naanu nanna maneyavaralli koodi Nandi Hills ge hoguttini.","Naale naanu nanna mitraru koodi Nandi Hills ge hoguttini.","Naale avaru nanna maneyavaralli koodi Nandi Hills ge hoguttini."],"correctAnswer":"Naale naanu nanna maneyavaralli koodi Nandi Hills ge hoguttini."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Naanu Goa trip ge ___ hoguttini, ticket book maadide.","options":["nishchayavaagi","belki","shaayada","munde ella"],"correctAnswer":"nishchayavaagi"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Let''s go together, it will be very good.","wordBankItems":["Koodi","hogona",",","thumba","channa","aguttade","."],"correctAnswer":"Koodi hogona , thumba channa aguttade ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"nishchaya means?","options":["certainty/determination","maybe/perhaps","desire","plan"],"correctAnswer":"certainty/determination"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000035',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe a person''s physical appearance in Kannada","Use ucchai/kadu for height and weight","Describe hair, eyes, and other features"],"explanation":{"intro":"Describing a person''s appearance covers physical descriptions including height, build, hair, eye color, and other identifying features in Kannada.","culturalNote":"Physical appearance in Karnataka culture: describing people politely is important in social contexts — often used when arranging introductions, giving directions, or describing missing persons. Skin tone: while fairer skin is often idealized in popular media, it is generally more respectful to describe complexion neutrally (saamanyana = average/normal, kannada culture: kaaLu meenu = dark and shiny complexion — sometimes considered attractive in traditional songs). Beauty standards vary across regions. Hair: Kannadigas have a variety of traditional hairstyles — Havyaka Brahmin women traditionally do a specific bun (muDi). Facial features: naakina = of the nose, kaLLina = of the eyes. Tilak marks (vibhuti on forehead, kumkum bindi — red dot) are common identifying features. Beard (gaDDa) and moustache (meese) are often described in identifying people."},"examples":[{"sentence":"Avaru thumba ucchai, neeli bana shirt haakitaare, haagu kaaLu gaDDa ide avarigu.","english":"He is very tall, wears a blue shirt, and has a black beard."},{"sentence":"Avalu madhyama ucchai, ulida kaLLu haagu channa naakku ide.","english":"She is of medium height, has curly hair and a nice nose."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can describe a person''s physical appearance in Kannada."}}',
'{"items":[{"word":"ucchai","translation":"height/tall","transliteration":"ucchai","pronunciation":"UC-chai","example":"thumba ucchai"},{"word":"kadu","translation":"short (in height)","transliteration":"kadu","pronunciation":"KA-du","example":"kadu manusha"},{"word":"gaDDa","translation":"beard","transliteration":"gaDDa","pronunciation":"GAD-da","example":"kaaLu gaDDa"},{"word":"kaLLu","translation":"hair (on head)","transliteration":"kaLLu","pronunciation":"KAL-lu","example":"ulida kaLLu"},{"word":"ulida","translation":"curly/wavy","transliteration":"ulida","pronunciation":"u-LI-da","example":"ulida kaLLu"},{"word":"naakku","translation":"nose","transliteration":"naakku","pronunciation":"NAAK-ku","example":"channa naakku"}]}',
'{"title":"Avaru thumba ucchai — He/She is very tall (appearance description)","pattern":"Avaru thumba ucchai = He/She is very tall (avaru = formal he/she/they — gender-neutral formal). Avanu = informal he. Avalu = informal she. Height: thumba ucchai (very tall), madhyama ucchai (medium height), kadu (short). Weight: doDDa maiyyu (big/heavy build — maiyyu = body). Hair: neeli kaLLu (straight hair), ulida kaLLu (curly hair), kaaLu kaLLu (black hair), bili kaLLu (white/grey hair). Build: thin = tallada (thin/slender), fat = jaasthi maiyyu/motti (fat). Eyes: doNNe kaLLu (big eyes — doNNe = big), neeli kaaNaali (blue eyes — rare — kaaNaali = pupil/iris).","explanation":"Person description in Kannada: start with height and build, then hair, then face features. Use avaru (formal — respectful, gender-neutral) for any adult you are describing respectfully. Use avanu (he) / avalu (she) only for people you know well or informally. Describing location: alli niltaare (standing there), ee barDa haakitaare (wearing this colour). Quick description for identifying: orange colour shirt haakida manushya (the man wearing an orange shirt). Adjective placement: always before the noun in Kannada (kaaLu kaLLa manushya = the black-haired person — kaaLu kaLLa = of black hair, adjective modifying manushya).","examples":[{"sentence":"Avanu tallada, kaaLu kaLLu haagu doNNe kaaNaali ide avanigu.","english":"He is thin, has black hair and has big eyes."},{"sentence":"Nanna akka madhyama ucchai, curly kaLLu haagu channa naakku ide.","english":"My sister is of medium height, has curly hair and a beautiful nose."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"kaLLu means?","options":["hair (on head)","eye","nose","beard"],"correctAnswer":"hair (on head)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"She is of medium height, has curly hair and a nice nose.","options":["Avalu madhyama ucchai, ulida kaLLu haagu channa naakku ide.","Avaru madhyama ucchai, ulida kaLLu haagu channa naakku ide.","Avalu thumba ucchai, ulida kaLLu haagu channa naakku ide.","Avalu madhyama ucchai, neeli kaLLu haagu channa naakku ide."],"correctAnswer":"Avalu madhyama ucchai, ulida kaLLu haagu channa naakku ide."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Avanu thumba ucchai, kaaLu ___ haagu doNNe kaaNaali ide avanigu.","options":["kaLLu","naakku","gaDDa","kaLLe"],"correctAnswer":"kaLLu"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He is very tall, wears a blue shirt, and has a black beard.","wordBankItems":["Avaru","thumba","ucchai",",","neeli","bana","shirt","haakitaare",",","haagu","kaaLu","gaDDa","ide","avarigu","."],"correctAnswer":"Avaru thumba ucchai , neeli bana shirt haakitaare , haagu kaaLu gaDDa ide avarigu ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"ulida means?","options":["curly/wavy","straight","black","long"],"correctAnswer":"curly/wavy"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000036',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss health and medical issues in Kannada","Use naakke X aagutte for describing symptoms","Ask about medicines and doctor''s advice"],"explanation":{"intro":"Health and medicine vocabulary covers how to describe symptoms, visit a doctor, ask for medicine, and discuss health conditions in Kannada.","culturalNote":"Healthcare in Karnataka: Bengaluru has excellent hospitals — Manipal Hospital, Narayana Health, Fortis, Apollo. Government hospitals: Victoria Hospital (one of the oldest and largest government hospitals in Bengaluru). AIIMS Bengaluru (new). Primary healthcare: PHC (Primary Health Centre) at village level. AYUSH (Ayurveda, Yoga, Unani, Siddha, Homeopathy) — government-promoted alternative medicine. Traditional medicine: Ayurveda is deeply rooted in Karnataka — Ayurvedic hospitals in Bengaluru, Mysuru. Yoga: S. Ramaswami and BKS Iyengar (Iyengar Yoga) from Karnataka. Common ailments: flu season during monsoon (July-September), dengue, chikungunya (mosquito-borne). Mental health: slowly gaining awareness in urban Karnataka. Insurance: government Ayushman Bharat scheme provides free treatment in empanelled hospitals."},"examples":[{"sentence":"Naakke thumba jwara aagutte haagu takka ide, doctor hattira hogabeku.","english":"I have a lot of fever and feel weak, I need to go to the doctor."},{"sentence":"Doctor, nanna hotte novu ide haagu channeeti maaduttiilla.","english":"Doctor, I have a stomachache and I am not feeling well."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can describe health symptoms and talk to a doctor in Kannada."}}',
'{"items":[{"word":"jwara","translation":"fever","transliteration":"jwara","pronunciation":"JWA-ra","example":"naakke jwara ide"},{"word":"novu","translation":"pain/ache","transliteration":"novu","pronunciation":"NO-vu","example":"nanna hotte novu"},{"word":"takka","translation":"weakness/fatigue (feeling weak)","transliteration":"takka","pronunciation":"TAK-ka","example":"thumba takka aagutte"},{"word":"dava","translation":"medicine","transliteration":"dava","pronunciation":"DA-va","example":"dava kodi"},{"word":"channeeti","translation":"feeling well/fine","transliteration":"channeeti","pronunciation":"chan-NEE-ti","example":"channeeti iddini"},{"word":"okkidu","translation":"get well soon/recover","transliteration":"okkidu","pronunciation":"ok-KI-du","example":"bega okkidu"}]}',
'{"title":"Naakke X aagutte — I have X (health symptom description)","pattern":"Naakke X aagutte = I have/feel X (symptom). Nanna X alli novu ide = I have pain in X (body part). Channeeti maaduttiilla = I am not feeling well. Doctor hattira hogabeku = I need to go to the doctor. Dava kodi = please give medicine. Prescription: dava cheethi (prescription — cheethi = note/chit). Tablet: tablet/capsule kodi (give tablet/capsule).","explanation":"Health vocabulary in Kannada: naakke = I have/I feel (dative of naanu). Jwara (fever), tala novu (headache — tala = head), hotte novu (stomachache — hotte = stomach), beenu novu (backache — beenu = back), kaLLu novu (eye pain — kaLLu = eye — different from hair!), kaLi novu (leg pain — kaLi = leg), maikke channeeti maaduttiilla (the body is not feeling well — maikke = to the body). Doctor visit: doctor avaru enu heldaare? (what did the doctor say?). Prescription: ee dava tinnu (take this medicine — tinnu = eat/take). Dosage: ooru sala (3 times — ooru = three), untu bande thinnu (take after eating — untu bande = after meals). Rest: visthaara vishranti beku (need complete rest).","examples":[{"sentence":"Nanna tala thumba novu ide, tablet kodi.","english":"I have a very bad headache, please give me a tablet."},{"sentence":"Ee dava tinnu, eradu dina takkad mele okkuttiri.","english":"Take this medicine, in two days you will recover with rest."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"jwara means?","options":["fever","headache","cough","cold"],"correctAnswer":"fever"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I have a lot of fever and feel weak, I need to go to the doctor.","options":["Naakke thumba jwara aagutte haagu takka ide, doctor hattira hogabeku.","Naakke thakku jwara aagutte haagu takka ide, doctor hattira hogabeku.","Naakke thumba jwara aagutte haagu takka ide, doctor hattira bandu.","Nimage thumba jwara aagutte haagu takka ide, doctor hattira hogabeku."],"correctAnswer":"Naakke thumba jwara aagutte haagu takka ide, doctor hattira hogabeku."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Nanna tala thumba novu ide, ___ kodi.","options":["tablet","dava","channeeti","jwara"],"correctAnswer":"tablet"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Doctor, I have a stomachache and I am not feeling well.","wordBankItems":["Doctor",",","nanna","hotte","novu","ide","haagu","channeeti","maaduttiilla","."],"correctAnswer":"Doctor , nanna hotte novu ide haagu channeeti maaduttiilla ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"channeeti means?","options":["feeling well/fine","feeling sick","getting better","medicine"],"correctAnswer":"feeling well/fine"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000037',1,'APPROVED','PUBLISHED',
'{"objectives":["Use mobile phone and telephone vocabulary in Kannada","Make a call and leave a message in Kannada","Understand missed call, message, and data usage terms"],"explanation":{"intro":"Telephone and mobile usage covers how to make calls, send messages, and discuss mobile phone activities in Kannada.","culturalNote":"Mobile culture in Karnataka: India is the world''s second-largest smartphone market. In Karnataka, mobile penetration is very high — even in rural areas. BSNL, Airtel, Jio (Reliance Jio — disrupted telecom with cheap data in 2016), Vi (Vodafone Idea). Bengaluru is a major hub for mobile app development — many global apps are developed here (Flipkart, Amazon India, Meesho). Missed call (missed call maadu) — a cultural practice: giving a ''missed call'' to signal something without charging money was very common before cheap data. UPI (Unified Payments Interface) — all payments now via mobile phone — PhonePe, GPay, Paytm are all Bengaluru-developed or headquartered. WhatsApp (widely used, even by grandparents). OTPs (one-time passwords) on mobile. Recharge: mobile recharge (prepaid top-up). Balance check: *121# (Airtel), *111# (Jio) — USSD codes."},"examples":[{"sentence":"Naanu ninage phone maaduttini, yaavaga siguttiri?","english":"I will call you, when will you be available?"},{"sentence":"Nanna phone battery hogide, later maatnaadona.","english":"My phone battery has died, let''s talk later."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can make calls, send messages, and talk about mobile phone activities in Kannada."}}',
'{"items":[{"word":"phone maadu","translation":"make a call (verb phrase)","transliteration":"phone maadu","pronunciation":"fon MAA-du","example":"naanu phone maaduttini"},{"word":"battery hogide","translation":"battery is dead/gone","transliteration":"battery hogide","pronunciation":"bat-TRI HO-gi-de","example":"battery hogide"},{"word":"signal","translation":"signal (network signal)","transliteration":"signal","pronunciation":"SIG-nal","example":"signal illa"},{"word":"message","translation":"message (SMS/WhatsApp)","transliteration":"message","pronunciation":"MES-sej","example":"message kali"},{"word":"maatnaadona","translation":"let''s talk (informal future suggestion)","transliteration":"maatnaadona","pronunciation":"maat-NAA-do-na","example":"later maatnaadona"},{"word":"siguttiri","translation":"will you be available/will I get you (formal)","transliteration":"siguttiri","pronunciation":"si-GUT-ti-ri","example":"yaavaga siguttiri?"}]}',
'{"title":"Naanu ninage phone maaduttini — I will call you (phone vocabulary)","pattern":"Naanu ninage phone maaduttini = I will call you (formal ninage = to you). Naanu phone maadide = I called (past). Phone etti = answered the phone (phone etti = pick up call — etti = pick up/lift). Missed call maadida = gave a missed call. Message kali = read the message. Battery hogide = battery died. Signal illa = no signal. Data = data (internet data). Recharge maadu = do a recharge.","explanation":"Phone vocabulary in Kannada: (1) Calling: phone maaduttini (I will call), phone etti (pick up the phone), phone irlu (put down the phone — hang up). (2) Messaging: message kali (read the message), message maadu (send a message). (3) Status: line busy (busy), network signal illa (no network signal), battery hogide (battery dead). (4) Video calling: video call maadu (make a video call). WhatsApp: WhatsApp message/call (same as English — used directly). (5) Asking when to call: yaavaga siguttiri? (when will I get you? — siguttiri = will I get/reach you, formal). Give me a missed call: ondu missed call kodi (give me one missed call).","examples":[{"sentence":"Naakke call bande itu aadare phone silent itu, sorry.","english":"A call came for me but the phone was on silent, sorry."},{"sentence":"WhatsApp message maadide, neevu nodiri.","english":"I sent a WhatsApp message, please check it (please see it)."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"phone maadu means?","options":["make a call","receive a call","send a message","hang up"],"correctAnswer":"make a call"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I will call you, when will you be available?","options":["Naanu ninage phone maaduttini, yaavaga siguttiri?","Naanu nimige phone maaduttini, yaavaga siguttiri?","Naanu ninage phone maadide, yaavaga siguttiri?","Naanu ninage phone maaduttini, eshtu gante ide?"],"correctAnswer":"Naanu ninage phone maaduttini, yaavaga siguttiri?"},{"id":"ex3","type":"FILL_IN_BLANK","question":"Nanna phone ___ hogide, later maatnaadona.","options":["battery","signal","message","data"],"correctAnswer":"battery"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I sent a WhatsApp message, please check it.","wordBankItems":["WhatsApp","message","maadide",",","neevu","nodiri","."],"correctAnswer":"WhatsApp message maadide , neevu nodiri ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"siguttiri means?","options":["will you be available/will I get you (formal)","are you calling","will you come","can you hear"],"correctAnswer":"will you be available/will I get you (formal)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000038',1,'APPROVED','PUBLISHED',
'{"objectives":["Learn vocabulary for Karnataka''s traditional arts in Kannada","Name famous art forms and their origins","Express appreciation for traditional arts"],"explanation":{"intro":"Karnataka''s traditional arts vocabulary covers the major classical and folk art forms of the state — dance, music, craft, and theatre — and how to talk about them in Kannada.","culturalNote":"Karnataka''s rich art heritage: (1) Yakshagana — coastal Karnataka''s ancient form of night-long dance-drama — combines elaborate costumes, music, and improvised dialogue. Two styles: Badagutittu (north style) and Tenkutittu (south style). (2) Dollu Kunitha — powerful drum dance by the Kuruba community — large dollu (drum) strapped to the body. (3) Veeragase — acrobatic warrior dance — with elaborate headgear. (4) Kamsale — temple dance with cymbals. (5) Bharatanatyam and Kuchipudi — classical forms very popular in Karnataka. (6) Carnatic music — Karnataka is home to major Carnatic musicians. (7) Mysuru Dasara — the state''s biggest cultural event showcasing all art forms. (8) Channapatna toys (lacquerware toys — UNESCO recognized Karnataka craft). (9) Bidriware (silver inlay on zinc alloy — from Bidar, North Karnataka). (10) Lambani needlework (mirror embroidery from North Karnataka — Sandur area)."},"examples":[{"sentence":"Yakshagana ide — ee Karnataka kalakalaa thumba prasiddha.","english":"There is Yakshagana — this is a very famous Karnataka art."},{"sentence":"Dollu Kunitha noduvudu naakke thumba ishtavagutte, ooru thumba taaLa.","english":"I really like watching Dollu Kunitha — the rhythm is very intense."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can name and discuss Karnataka''s traditional art forms in Kannada."}}',
'{"items":[{"word":"kalaakoota","translation":"art form (general term for traditional art)","transliteration":"kalaakoota","pronunciation":"ka-laa-KOO-ta","example":"Karnataka kalaakoota"},{"word":"naaTaka","translation":"play/drama/theatre","transliteration":"naaTaka","pronunciation":"NAA-Ta-ka","example":"naaTaka aadaare"},{"word":"taaLa","translation":"rhythm/beat","transliteration":"taaLa","pronunciation":"TAA-La","example":"taaLa haakuttaare"},{"word":"aaduvudu","translation":"to dance (verbal noun: dancing)","transliteration":"aaduvudu","pronunciation":"aa-DU-vu-du","example":"aaduvudu channa"},{"word":"haaDu","translation":"song","transliteration":"haaDu","pronunciation":"HAA-Du","example":"channa haaDu"},{"word":"Dasara","translation":"Dasara festival (Mysuru''s famous 10-day festival)","transliteration":"Dasara","pronunciation":"DA-sa-ra","example":"Mysuru Dasara"}]}',
'{"title":"Karnataka kalaakoota — Karnataka art forms vocabulary","pattern":"X ee Karnataka kalaakoota = X is a Karnataka art form. Yakshagana / Dollu Kunitha / Bharatanatyam — proper nouns used directly. Appreciating: ee X noduvudu naakke ishtavagutte (I like watching X — noduvudu = watching, verbal noun). Prasiddha = famous/renowned. Hundi kalaakoota = ancient art form (hundi = ancient/old). Taalamele aaduttaare = they dance on a beat (taalamele = on the beat).","explanation":"Karnataka art vocabulary: kalaakoota (art form), naaTaka (drama/play), haaDu (song), aaTa (dance), taaLa (rhythm), vesha (costume/attire — vesha haakuttaare = they wear costume). Art appreciation: ee kalaakoota noduvudu naakke thumba ishtavagutte (I really like watching this art form). Describing performance: avaru thumba channa aaduttaare (they dance very beautifully). Asking about: ee X yaav jileyinda bandide? (this X came from which district?). Origin: X Y jileyinda vandide (X came from Y district). Unique feature: X nalli vesha (X has costumes).","examples":[{"sentence":"Yakshagana karavali Karnataka inda bandide haagu thumba hundi kalaakoota.","english":"Yakshagana came from coastal Karnataka and is a very ancient art form."},{"sentence":"Naanu Dasara habba noduvudu naakke thumba ishtavagutte, Mysuru alli thumba channa aguttade.","english":"I really like watching the Dasara festival, it is very beautiful in Mysuru."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"taaLa means?","options":["rhythm/beat","song","dance","costume"],"correctAnswer":"rhythm/beat"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"There is Yakshagana — this is a very famous Karnataka art.","options":["Yakshagana ide — ee Karnataka kalakalaa thumba prasiddha.","Dollu Kunitha ide — ee Karnataka kalakalaa thumba prasiddha.","Yakshagana ide — ee Karnataka kalakalaa thakku prasiddha.","Yakshagana ide — ee Tamil Nadu kalakalaa thumba prasiddha."],"correctAnswer":"Yakshagana ide — ee Karnataka kalakalaa thumba prasiddha."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Yakshagana karavali Karnataka inda bandide haagu thumba hundi ___ .","options":["kalaakoota","naaTaka","haaDu","taaLa"],"correctAnswer":"kalaakoota"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I really like watching the Dasara festival.","wordBankItems":["Naanu","Dasara","habba","noduvudu","naakke","thumba","ishtavagutte","."],"correctAnswer":"Naanu Dasara habba noduvudu naakke thumba ishtavagutte ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"haaDu means?","options":["song","dance","rhythm","drama"],"correctAnswer":"song"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000039',1,'APPROVED','PUBLISHED',
'{"objectives":["Use vocabulary for post office and bank in Kannada","Post a letter and make a transaction in Kannada","Understand common banking terms in Kannada"],"explanation":{"intro":"Post office and bank vocabulary covers how to post letters and parcels, make deposits and withdrawals, and ask for banking services in Kannada.","culturalNote":"Banking and post office in Karnataka: (1) India Post — post office (aSTe) is ubiquitous. In rural Karnataka, India Post is still the main financial service provider — post office savings account (POSb), Kisan Vikas Patra. (2) Banks: SBI (State Bank of India — government bank, largest, very trusted), Canara Bank (headquartered in Bengaluru — Karnataka''s own major bank), Syndicate Bank (merged with Canara), Corporation Bank (merged with Union Bank). Private: HDFC, ICICI, Axis. (3) UPI revolution: BHIM UPI has transformed payments — scanning QR code at any shop. (4) Bengaluru innovation: Infosys campus has its own bank branch. Many banks have branches on every street in Bengaluru. (5) ATM (ATM — used directly). (6) Cheque (cheque/check) — used for large official payments. (7) Fixed Deposit (FD): very popular for savings. (8) Passbook: passbook update maadu (update passbook) is common in PSB banks."},"examples":[{"sentence":"Naanu ee patira post maadabeku, eshtu aagutte?","english":"I want to post this letter, how much will it cost?"},{"sentence":"Naakke account inda X rupai tEgeyabeku, ATM card beku.","english":"I want to withdraw X rupees from my account, I need an ATM card."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can handle post office and banking transactions in Kannada."}}',
'{"items":[{"word":"asTe","translation":"post office","transliteration":"asTe","pronunciation":"as-Te","example":"asTe ge hode"},{"word":"patira","translation":"letter/document","transliteration":"patira","pronunciation":"pa-TI-ra","example":"patira post maadu"},{"word":"tEgeyu","translation":"withdraw (take out from account)","transliteration":"tEgeyu","pronunciation":"TE-ge-yu","example":"account inda tEgeyabeku"},{"word":"haaku","translation":"deposit (put into account)","transliteration":"haaku","pronunciation":"HAA-ku","example":"account ge haakabeku"},{"word":"passbook","translation":"bank passbook","transliteration":"passbook","pronunciation":"PAS-buk","example":"passbook update maadu"},{"word":"interest","translation":"interest (bank interest)","transliteration":"interest","pronunciation":"IN-tres","example":"yaavadu interest?"}]}',
'{"title":"Naakke account inda X rupai tEgeyabeku — bank and post office vocabulary","pattern":"Naakke account inda X tEgeyabeku = I want to withdraw X from my account. Naakke account ge X haakabeku = I want to deposit X into my account. Post: ee patira post maadabeku (I want to post this letter). Speed post: ee parcel speed post maadabeku (I want to send this parcel by speed post). Courier: courier maadu (send by courier). Balance: naanna account balance eshtu ide? (what is my account balance?).","explanation":"Post office vocabulary: patira (letter), parcel (parcel), speed post (speed post), registered post (registered post), stamp (stamp), address (address). Sending: X ge patira post maadu (post a letter to X). Bank vocabulary: account (bank account), balance (balance), tEgeyabeku (withdraw), haakabeku (deposit), passbook (passbook), cheque (cheque), RTGS/NEFT/IMPS (transfer). ATM: ATM inda hana tEgeyu (withdraw money from ATM). Online: net banking through website. Statement: account statement (bank statement). KYC: KYC update maadu (update KYC — Know Your Customer — mandatory).","examples":[{"sentence":"Naakke ee parcel Delhi ge speed post maadabeku, yaavaga thaLuputtade?","english":"I want to send this parcel to Delhi by speed post, when will it arrive?"},{"sentence":"Nanna account balance eshtu ide? Ondu hajar rupai tEgeyabeku.","english":"What is my account balance? I want to withdraw one thousand rupees."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"tEgeyu means?","options":["withdraw (take out from account)","deposit","transfer","check balance"],"correctAnswer":"withdraw (take out from account)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I want to post this letter, how much will it cost?","options":["Naanu ee patira post maadabeku, eshtu aagutte?","Naanu ee parcel post maadabeku, eshtu aagutte?","Naanu ee patira speed post maadabeku, eshtu aagutte?","Naanu ee patira post maadide, eshtu aayitu?"],"correctAnswer":"Naanu ee patira post maadabeku, eshtu aagutte?"},{"id":"ex3","type":"FILL_IN_BLANK","question":"Naakke account inda X rupai ___ , ATM card beku.","options":["tEgeyabeku","haakabeku","nodabeku","maadabeku"],"correctAnswer":"tEgeyabeku"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: What is my account balance? I want to withdraw one thousand rupees.","wordBankItems":["Nanna","account","balance","eshtu","ide","?","Ondu","hajar","rupai","tEgeyabeku","."],"correctAnswer":"Nanna account balance eshtu ide ? Ondu hajar rupai tEgeyabeku ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"haaku means?","options":["deposit (put into account)","withdraw","transfer","invest"],"correctAnswer":"deposit (put into account)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-00000000003a',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe relationships in Kannada","Use X nanna Y anta parichaya maadisuttini for introductions","Talk about friends, colleagues, and relationships"],"explanation":{"intro":"Describing relationships covers how to introduce people, describe how you know someone, and talk about different types of relationships in Kannada.","culturalNote":"Relationships in Karnataka culture: family relationships are very formalized in Kannada with specific terms for every type of relative. Joint families are still common in many parts of Karnataka. Marriage: arranged marriage is still the norm for most Kannadigas, though love marriages are increasingly accepted, especially in urban areas. Matrimonial ads: published in Deccan Herald, Prajavani (Kannada newspaper). Caste: caste still plays a role in marriage decisions — Lingayat, Vokkaliga, Brahmin communities have specific matrimonial networks. Friendship: mitraru (friend — formal plural/singular), geleya (close friend — informal male), geleti (close female friend). Colleagues: kaaryadalli geleya (work friend/colleague — kaaryadalli = at work). Neighbors: padatte/pakkadamane manushya (neighbor — pakkadamane = next-door house). Community ties (ooru = village/hometown — people from the same ooru have strong bonds even in Bengaluru)."},"examples":[{"sentence":"Ee Priya, nanna kolege kaaryadalli geleya.","english":"This is Priya, my colleague at work."},{"sentence":"Avaru nanna munde inda geleya, naavu shaaleyalli koodi odide.","english":"He/She is my old friend, we studied together in school."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can describe relationships, introduce people, and talk about how I know someone in Kannada."}}',
'{"items":[{"word":"geleya","translation":"close friend (informal male)","transliteration":"geleya","pronunciation":"ge-LE-ya","example":"nanna geleya"},{"word":"geleti","translation":"close friend (informal female)","transliteration":"geleti","pronunciation":"ge-LE-ti","example":"nanna geleti"},{"word":"mitra","translation":"friend (formal/neutral)","transliteration":"mitra","pronunciation":"MI-tra","example":"nanna mitra"},{"word":"kolege","translation":"colleague/coworker","transliteration":"kolege","pronunciation":"KO-le-ge","example":"kaaryadalli kolege"},{"word":"parichaya","translation":"introduction/acquaintance","transliteration":"parichaya","pronunciation":"pa-RI-cha-ya","example":"parichaya maadisuttini"},{"word":"baddu","translation":"relationship/connection","transliteration":"baddu","pronunciation":"BAD-du","example":"channa baddu"}]}',
'{"title":"Ee X, nanna Y — This is X, my Y (introducing a relationship)","pattern":"Ee X, nanna Y = This is X, my Y. Nanna geleya/geleti/mitra/kolege (my friend/colleague). Introducing: X nanna Y anta parichaya maadisuttini (I introduce X as my Y — parichaya = introduction). Describing how you know them: naavu X alli koodi odide/maadide/aaDidde = we together did X. Duration: X varsha inda geleya (friend for X years).","explanation":"Relationship vocabulary in Kannada: geleya (close male friend), geleti (close female friend), mitra/mitraru (friend — neutral/formal), kolege (colleague), sihi geleya (childhood friend — sihi = sweet/childhood — sweet friend!). Family intro: ee nanna amma avaru (this is my mother). Non-family intro: ee nanna kaaryaalaya alli kolege (this is my office colleague). How you met: shaaleyalli sigida (met in school), college alli sikida (found in college), kaelada moolaka (through work). Duration: naavu X varsha inda geleya (we have been friends for X years). Social circle: padatte maneyavaru (neighbors — padatte = nearby/adjacent — with maneyavaru = house people).","examples":[{"sentence":"Ee Kiran, nanna college kalada geleya, naavu ondu sala koodi Coorg ge hogidde.","english":"This is Kiran, my friend from college days, we once went to Coorg together."},{"sentence":"Naavu X varsha inda mitraru, avarigu nanna mele thumba vishwaasa ide.","english":"We have been friends for X years, they have a lot of trust in me."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"geleya means?","options":["close friend (informal male)","formal friend","colleague","neighbor"],"correctAnswer":"close friend (informal male)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"This is Priya, my colleague at work.","options":["Ee Priya, nanna kolege kaaryadalli geleya.","Ee Raju, nanna kolege kaaryadalli geleya.","Ee Priya, nanna mitra kaaryadalli geleya.","Ee Priya, nanna kolege shaaleyalli geleya."],"correctAnswer":"Ee Priya, nanna kolege kaaryadalli geleya."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Avaru nanna munde inda geleya, naavu shaaleyalli koodi ___ .","options":["odide","hode","maadide","tinde"],"correctAnswer":"odide"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: This is Kiran, my friend from college days.","wordBankItems":["Ee","Kiran",",","nanna","college","kalada","geleya","."],"correctAnswer":"Ee Kiran , nanna college kalada geleya ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"parichaya means?","options":["introduction/acquaintance","relationship","friendship","meeting"],"correctAnswer":"introduction/acquaintance"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-00000000003b',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about movies and TV in Kannada","Use X film nodide for discussing films","Name Kannada film industry terms"],"explanation":{"intro":"Movies and TV vocabulary covers how to discuss films, TV shows, actors, and entertainment in Kannada.","culturalNote":"Kannada film industry (Sandalwood): Sandalwood is the Kannada language film industry — named after the sandalwood (Chandana) abundant in Karnataka. Based primarily in Bengaluru (Film Nagar and Rajajinagar areas). Major directors: Kashinath (director-actor — remembered fondly), Upendra (actor-director-writer — avant-garde films), Yogaraj Bhat (Mungaru Male — 2006 — one of the biggest Kannada hits), Rakshit Shetty (Ulidavaru Kandante — art film, Kirik Party — mainstream). Stars: Puneeth Rajkumar (Appu — the late superstar — son of Dr. Rajkumar — loved by all Kannadigas, passed away 2021), Sudeep (Kiccha Sudeep — action star), Shiva Rajkumar (Shivaanna — very popular). Sandalwood hits: Mungaru Male, Ulidavaru Kandante, Kirik Party, KGF (made in Kannada — Yash — became a national blockbuster). OTT: Netflix/Prime Video/Zee5/Hotstar have Kannada content. Kannadiga film songs are famous for their emotionality."},"examples":[{"sentence":"Ninne naanu ondu Sandalwood film nodide, thumba channa itu.","english":"Yesterday I watched a Sandalwood film, it was very good."},{"sentence":"Nimage Puneeth Rajkumar avara film ishtavagutte aa? Naakke thumba ishtavagutte.","english":"Do you like Puneeth Rajkumar''s films? I really like them."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can discuss films, TV, and entertainment in Kannada."}}',
'{"items":[{"word":"film","translation":"film/movie","transliteration":"film","pronunciation":"film","example":"channa film"},{"word":"nodide","translation":"watched (past of nodi = see/watch)","transliteration":"nodide","pronunciation":"NO-di-de","example":"film nodide"},{"word":"naaTaka","translation":"play/drama (stage)","transliteration":"naaTaka","pronunciation":"NAA-Ta-ka","example":"naaTaka noduttiini"},{"word":"heroine","translation":"heroine/actress","transliteration":"heroine","pronunciation":"he-ROY-ne","example":"channa heroine"},{"word":"hero","translation":"hero/actor (leading)","transliteration":"hero","pronunciation":"HI-ro","example":"nanna iShTa hero"},{"word":"release","translation":"release (film release)","transliteration":"release","pronunciation":"ri-LEES","example":"new release"}]}',
'{"title":"X film nodide — I watched X film (discussing movies)","pattern":"Naanu X film nodide = I watched X film. X ee vaara release aagide = X released this week. Actor/heroine: nanna iShTa hero/heroine X (my favorite actor/heroine is X). Genre: X thriller/comedy/drama/horror film (same English words used). Rating: X film thumba channa itu (X film was very good). Recommend: neevu X film nodiri, thumba channa aguttade (you watch X film, it will be very good).","explanation":"Film vocabulary in Kannada: film (film), hero (lead male), heroine (lead female), director (director), ooTa (climax — from ''oota'' but used for dramatic reveal). Genre terms: action, comedy, drama, thriller, horror — all English words used directly in Kannada. Film review: film thumba channa itu / channa agalilla (it was very good / it was not good). Song: film alli haaDu thumba channa (the songs in the film are very good). OTT: OTT alli nodide (I watched on OTT). Theatre: theatre alli nodide (I watched in a cinema/theatre). Favorite: iShTa = liked/favorite (nanna iShTa = my favorite). Kannada film: Kannada film = Sandalwood film (Sandalwood is the term used).","examples":[{"sentence":"Neevu KGF film nodidiri aa? Thumba channa aguttade, Yash acting thumba channaagi ide.","english":"Have you watched the KGF film? It is very good, Yash''s acting is very nice."},{"sentence":"Naanu OTT alli Sandalwood film nodide, ee vaara renDu film nodide.","english":"I watched a Sandalwood film on OTT, I watched two films this week."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"nodide means?","options":["watched/saw (past tense)","I will watch","watching","watch"],"correctAnswer":"watched/saw (past tense)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Yesterday I watched a Sandalwood film, it was very good.","options":["Ninne naanu ondu Sandalwood film nodide, thumba channa itu.","Inja naanu ondu Sandalwood film nodide, thumba channa itu.","Ninne avanu ondu Sandalwood film nodide, thumba channa itu.","Ninne naanu ondu Bollywood film nodide, thumba channa itu."],"correctAnswer":"Ninne naanu ondu Sandalwood film nodide, thumba channa itu."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Naanu OTT alli Sandalwood film nodide, ee vaara renDu film ___ .","options":["nodide","hogide","tinide","bande"],"correctAnswer":"nodide"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Have you watched the KGF film? It is very good.","wordBankItems":["Neevu","KGF","film","nodidiri","aa","?","Thumba","channa","aguttade","."],"correctAnswer":"Neevu KGF film nodidiri aa ? Thumba channa aguttade ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"release means?","options":["release (film release)","premiere","showing","screening"],"correctAnswer":"release (film release)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-00000000003c',1,'APPROVED','PUBLISHED',
'{"objectives":["Review all three Kannada tenses: past, present, habitual","Use negation correctly in all three tenses","Consolidate core A1 grammar structures"],"explanation":{"intro":"A1 grammar review covers the three main tenses (habitual present, simple past, near future), negation forms, and the key grammatical patterns from all A1 lessons.","culturalNote":"Kannada grammar heritage: Kannada has one of the longest grammatical histories of any Dravidian language — the oldest Kannada inscription dates to around 450 CE (Halmidi inscription). The language evolved through Old Kannada (Hale Kannada — used in inscriptions), Middle Kannada (Nadugannada), and Modern Kannada (Hosagannada). Grammar texts: Keshiraja''s Shabdamanidarpana (12th century) is the first systematic Kannada grammar. Dialect variation: Coastal (Tulu-influenced), North Karnataka (Urdu-influenced), Mysuru region (classical). Literary Kannada vs. colloquial: literary Kannada (granthabhaashe) is more formal and used in formal writing; colloquial (vyavahaarabhaashe) is everyday speech. This course teaches colloquial Kannada as used in Bengaluru and Mysuru."},"examples":[{"sentence":"Naanu pratidinaa kaapi kudiyuttini (habitual), ninne tinde (past), naale kudiyuttini (future).","english":"I drink coffee every day (habitual), yesterday I ate (past), tomorrow I will drink (future)."},{"sentence":"Avanu hoguttaane (he goes), Avanu hoguttilla (he doesn''t go), Avanu hodaanu (he went).","english":"He goes (present), He doesn''t go (negative), He went (past)."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":20,"canDo":"I have mastered Kannada A1 grammar: three tenses, negation, and all key sentence patterns."}}',
'{"items":[{"word":"hoguttini","translation":"I go/am going (habitual/near future 1st person)","transliteration":"hoguttini","pronunciation":"ho-GUT-ti-ni","example":"naanu hoguttini"},{"word":"hode","translation":"I went (past 1st person)","transliteration":"hode","pronunciation":"HO-de","example":"naanu hode"},{"word":"hoguttilla","translation":"I don''t go/am not going (habitual negative)","transliteration":"hoguttilla","pronunciation":"ho-GUT-til-la","example":"naanu hoguttilla"},{"word":"hodilla","translation":"I didn''t go (past negative)","transliteration":"hodilla","pronunciation":"HO-dil-la","example":"naanu hodilla"},{"word":"beku","translation":"need/want (necessity/desire particle)","transliteration":"beku","pronunciation":"BE-ku","example":"naakke beku"},{"word":"beda","translation":"don''t want/don''t need (negative of beku)","transliteration":"beda","pronunciation":"BE-da","example":"naakke beda"}]}',
'{"title":"A1 Grammar review — tenses and negation in Kannada","pattern":"Habitual present: verb stem + -uttini (1st sg), -uttini (1st sg), -uttaane (3rd m), -uttaaLe (3rd f), -uttaare (3rd formal). Past: verb stem + -de (most verbs 1st/2nd), -da (3rd). Negative: habitual = verb stem + -uttilla. Past negative = verb stem + -alla/-illa depending on verb class. Beku (need/want) vs beda (don''t want). Need: naakke X beku (I need X). Refusal: naakke X beda (I don''t want X).","explanation":"A1 Grammar summary for Kannada: (1) HABITUAL PRESENT: verb + uttini (I), uttini (you-info), uttiri (you-formal), uttaane (he-info), uttaaLe (she-info), uttaare (he/she formal), uttaare (they formal). Example: hogi+uttini = hoguttini (I go). (2) PAST TENSE: verb+de (first person — naanu hode = I went), verb+da (third person — avanu hoda = he went), verb+daru (they went — avaru hodaru). (3) NEGATION habitual: verb+uttilla (naanu hoguttilla = I don''t go). (4) PAST NEGATION: naanu hodilla (I didn''t go). (5) BEKU/BEDA: naakke X beku (I need X), naakke X beda (I don''t want X). (6) KEY PATTERNS: alli = location, ge = direction, inda = from/since/by, haagu = and/also, aadare = but, yaakenendare = because.","examples":[{"sentence":"Naanu Kannada kalivuttiddeeni, thumba ishtavagutte — A2 ge hogona!","english":"I am learning Kannada, I really like it — let''s go to A2!"},{"sentence":"Naanu A1 poorthi maadide, A2 shuru maaduttini.","english":"I have completed A1, I will start A2."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"hoguttilla means?","options":["I don''t go/am not going (habitual negative)","I will not go","I haven''t gone","I can''t go"],"correctAnswer":"I don''t go/am not going (habitual negative)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I drink coffee every day (habitual), yesterday I ate (past), tomorrow I will drink (future).","options":["Naanu pratidinaa kaapi kudiyuttini (habitual), ninne tinde (past), naale kudiyuttini (future).","Naanu pratidinaa kaapi kudide (habitual), ninne tinde (past), naale kudiyuttini (future).","Naanu pratidinaa kaapi kudiyuttini (habitual), inja tinde (past), naale kudiyuttini (future).","Avanu pratidinaa kaapi kudiyuttini (habitual), ninne tinde (past), naale kudiyuttini (future)."],"correctAnswer":"Naanu pratidinaa kaapi kudiyuttini (habitual), ninne tinde (past), naale kudiyuttini (future)."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Naanu A1 poorthi maadide, A2 shuru ___ .","options":["maaduttini","maadide","maaduttini","maadabeku"],"correctAnswer":"maaduttini"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I have completed A1, I will start A2.","wordBankItems":["Naanu","A1","poorthi","maadide",",","A2","shuru","maaduttini","."],"correctAnswer":"Naanu A1 poorthi maadide , A2 shuru maaduttini ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"beda means?","options":["don''t want/don''t need","need","want","should"],"correctAnswer":"don''t want/don''t need"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

